"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["2669"],{53949(e){e.exports=JSON.parse('{"id":"V4-004","slug":"critical-illness-insurance","term":"Critical Illness Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Critical illness insurance is insurance that pays a tax-free lump sum, in many countries, if the policyholder is diagnosed with one of a list of serious conditions, such as certain cancers, heart attacks or strokes.","explanation":["A serious illness can bring large costs and lost income, even if the person survives. Critical illness insurance provides a lump sum that can be used for anything, such as paying off a mortgage, covering living costs during treatment, adapting a home or paying for private care.","Each policy lists the conditions it covers and defines them precisely, often including how severe the illness must be. Common conditions include specified cancers, heart attack, stroke, multiple sclerosis and major organ failure.","For example, someone diagnosed with a covered cancer might receive 100,000, allowing them to take time off work during treatment without worrying about their mortgage payments.","Critical illness cover is common in the United Kingdom, Australia, Canada and parts of Asia, often bought alongside life insurance. It differs from income protection, which pays a regular income while someone cannot work, and from health insurance, which pays medical bills. Claims can be refused if a condition does not meet the policy\u2019s definition or if health information was not disclosed when buying, so reading the definitions carefully matters."],"note":"","total":1725,"prev":{"slug":"credit-utilization","term":"Credit Utilization"},"next":{"slug":"cross-border-payment","term":"Cross-Border Payment"}}')}}]);